// Runs in the report's commit, so a refused report writes nothing, and a replay finds its own report stored.
const stored = new VerificationRecord(previous);
const refusal = stored.refusal(verification);
if (refusal !== undefined) throw new Error(refusal);
const kept = stored.after(verification);
if (JSON.stringify(previous) === JSON.stringify(kept)) return stored.whole(verification);

whole(report: Verification): boolean {
	const { stored } = this;
	return (
		stored === undefined ||
		JSON.stringify(stored) === JSON.stringify(withDifferent(report, stored)) ||
		verdictStrength[report.verdict] > verdictStrength[stored.verdict]
	);
}

/**
 * Why `report` cannot follow the stored report of its claim, or `undefined` when it may: it replaces the stored
 * report, or it answers `different` for a dismissed finding the stored report did not. Otherwise the first report
 * stands, so a second call cannot overwrite its reason or undo its lowering.
 */
refusal(report: Verification): string | undefined {
	const { stored } = this;
	if (stored === undefined || this.whole(report)) return undefined;
	if (
		Object.entries(report.matches ?? {}).some(
			([id, answer]) => answer === "different" && stored.matches?.[id] !== "different",
		)
	)
		return undefined;
	const lowered = stored.lowered === undefined ? "" : `, lowered ${stored.lowered.from} to ${stored.lowered.to}`;
	return `this claim is already judged ${stored.verdict}${lowered}, and a later report of it is taken only at a stronger verdict or for a different sameness answer it lacks, so the first report stands with its reason`;
}

it("takes a later different sameness answer over a stored same, at an equal verdict, and never takes it back", async () => {
	const dismissed = "0123456789abcdef";
	const { harness, root } = await open(createMemoryStorage());
	await root.commit((tx) => upsertFinding(tx, root.id, evalFinding, "rev1"), context);
	await judge(root, { ...lowered, matches: { [dismissed]: "same" } });
	const correction = { ...record, reason: "Another path.", matches: { [dismissed]: "different" } } as const;
	await expect(judge(root, correction)).resolves.toBe(false);
	const kept = { ...lowered, matches: { [dismissed]: "different" } };
	expect((await readFindings(harness, root.id, "rev1", context))[0]!.properties.verification).toEqual(kept);
	const version = await findingsVersion(harness, root.id, "rev1", context);
	await expect(judge(root, { ...lowered, matches: { [dismissed]: "same" } })).resolves.toBe(true);
	await expect(
		judge(root, { ...lowered, reason: "Same after all.", matches: { [dismissed]: "same" } }),
	).rejects.toThrow("this claim is already judged confirmed");
	expect(await findingsVersion(harness, root.id, "rev1", context)).toBe(version);
	expect((await readFindings(harness, root.id, "rev1", context))[0]!.properties.verification).toEqual(kept);
});

